CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TYPE report_category AS ENUM ('luminaire_off','intermittent_or_damaged','insufficient_street_lighting','obstructed_lighting');
CREATE TYPE report_status AS ENUM ('pending_review','published','needs_information','rejected');
CREATE TYPE case_status AS ENUM ('open','submitted_to_authority','in_progress','repaired_unverified','repaired_verified','closed');
CREATE TYPE update_kind AS ENUM ('institutional_response','reported_intervention','field_verification');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'citizen' CHECK(role IN ('citizen','moderator','admin')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), category report_category NOT NULL, observed_at timestamptz NOT NULL, description text NOT NULL, context text NOT NULL DEFAULT '', location geography(Point,4326) NOT NULL, status report_status NOT NULL DEFAULT 'pending_review', review_reason text, reviewed_by uuid REFERENCES users(id), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reports_location_gix ON reports USING GIST(location); CREATE INDEX reports_status_created_idx ON reports(status,created_at DESC);
CREATE TABLE evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, storage_key text NOT NULL, mime_type text NOT NULL, byte_size integer NOT NULL CHECK(byte_size > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE confirmations (report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(report_id,user_id));
CREATE TABLE cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, summary text NOT NULL, area_description text NOT NULL DEFAULT '', status case_status NOT NULL DEFAULT 'open', created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE case_reports (case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE, report_id uuid NOT NULL REFERENCES reports(id), PRIMARY KEY(case_id,report_id));
CREATE TABLE case_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES users(id), old_status case_status, new_status case_status NOT NULL, note text NOT NULL DEFAULT '', evidence_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE official_folios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE, authority text NOT NULL, channel text NOT NULL, folio text NOT NULL, submitted_at timestamptz NOT NULL, receipt_url text NOT NULL, notes text NOT NULL DEFAULT '', created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE case_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES users(id), kind update_kind NOT NULL, summary text NOT NULL, observed_at timestamptz NOT NULL, evidence_url text, is_public boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
-- submitted_to_authority is set only in the transaction that records receipt evidence.
CREATE OR REPLACE FUNCTION require_receipt_for_submission() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='submitted_to_authority' AND OLD.status IS DISTINCT FROM NEW.status AND NOT EXISTS (SELECT 1 FROM official_folios WHERE case_id=NEW.id AND receipt_url <> '') THEN RAISE EXCEPTION 'receipt evidence required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cases_receipt_guard BEFORE UPDATE OF status ON cases FOR EACH ROW EXECUTE FUNCTION require_receipt_for_submission();
